#!/usr/bin/env python3
"""Sentence-based, manually reviewed triage of the complete stattree frontier.

From the project root (Python 3 plus the existing requests package):
  PYTHONDONTWRITEBYTECODE=1 python scripts/frontier_triage.py
  PYTHONDONTWRITEBYTECODE=1 python scripts/frontier_triage.py --offline
  PYTHONDONTWRITEBYTECODE=1 python scripts/frontier_triage.py --check

CURATION below retains a decision for each work, the precise supporting context
IDs, and the bibliography aliases reviewed together. It is intentionally a
sentence reading, not a keyword classifier. Neither citation counts, row order,
graph depth nor seed distance determines a role, kind or follow decision.
Alternative/proposed method components count when the sentence supplies them;
simulation-only models, benchmark algorithms and diagnostic metrics do not.
Generic inspiration is recorded only to the extent stated in the sentence.

Every context for each reviewed bibliography identity is joined to its optional
context_links rows. The output lists only evidence supporting the selected role;
tmp/refresh/triage_audit.json records all considered context IDs and sentence
fingerprints. On changed sentences, a diagnostic requests renewed manual review.

Each followed work gets one logical Europe PMC core-metadata search. Transport
retries use the identical URL, retain all attempts, and are not additional search
queries. Only public repository metadata is requested, without personal netrc
credentials. Cache files live in sources/citations_cache/. A successful empty
search, or matched metadata with no allowed full-text route, is none_found.
Transport/service errors are failures, never none_found. Retained OpenAlex repository locations supplement the single search without
additional network requests. The route identifies a repository location; this script does not download or assert full-text access.
NA is used for works not followed. Offline reruns use the same response cache.
Writes: this script's requested TSV, metadata cache and tmp/refresh/ only.
"""
import argparse
import csv
import hashlib
import html
import json
import re
import sys
import time
import unicodedata
from collections import Counter, defaultdict
from concurrent.futures import ThreadPoolExecutor, as_completed
from difflib import SequenceMatcher
from functools import lru_cache
from pathlib import Path
from urllib.parse import urlencode, urlsplit

ROOT = Path(__file__).resolve().parents[1]
EPMC = 'https://www.ebi.ac.uk/europepmc/webservices/rest/search'
FIELDS = ['cited_first_author', 'cited_year', 'cited_title', 'cited_doi',
          'cited_label', 'citing_papers', 'lineage_role', 'paper_kind', 'follow',
          'why', 'context_ids', 'open_route', 'proposed_paper_id']
IDENTITY_FIELDS = FIELDS[:5]
LINEAGE = {'model', 'prior', 'likelihood', 'fitting_algorithm', 'theory',
           'estimand', 'predecessor'}
ROLES = LINEAGE | {'evaluation', 'data_processing', 'data', 'software',
                   'application', 'background'}
FOLLOW_KINDS = {'statistical_method', 'algorithm', 'theory', 'review_or_textbook'}
KINDS = FOLLOW_KINDS | {'data_resource', 'software', 'applied_study'}
ROUTES = {'pmc', 'europepmc', 'arxiv', 'biorxiv', 'none_found'}


def norm(value):
    value = unicodedata.normalize('NFKD', html.unescape(str(value)))
    return re.sub('[^a-z0-9]', '', value.encode('ascii', 'ignore').decode().lower())


def present(value):
    return str(value or '').strip() not in {'', 'NA', 'None'}


def doi(value):
    match = re.search(r'10\.\d{4,9}/[^\s<>"\\&#?]+', html.unescape(str(value)), re.I)
    return match.group().rstrip('.,;:)').lower() if match else ''


def identity(row):
    return doi(row.get('cited_doi', '')) or norm(row['cited_title'])


def read_table(path):
    with path.open(newline='', encoding='utf-8') as handle:
        reader = csv.DictReader(handle, delimiter='\t')
        return reader.fieldnames, list(reader)


def expected_follow(role, kind):
    return 'yes' if role in LINEAGE and kind in FOLLOW_KINDS else 'no'


def snake(value):
    value = unicodedata.normalize('NFKD', value).encode('ascii', 'ignore').decode()
    return re.sub('[^a-z0-9]+', '_', value.lower()).strip('_')


def author_id(row):
    author = row['cited_first_author'].split('&')[0].split(',')[0].strip()
    # Repair author strings that include concatenated bibliography fields.
    for marker, name in [('International HapMap Consortium', 'international_hapmap_consortium'),
                         ('ENCODE Project Consortium', 'encode_project_consortium'),
                         ('Schizophrenia Working Group', 'schizophrenia_working_group'),
                         ('The GTEx Consortium', 'gtex_consortium')]:
        if author.startswith(marker):
            return name
    tokens = author.split()
    while len(tokens) > 1 and re.fullmatch(r'[A-Z.]{1,4}', tokens[0]):
        tokens.pop(0)
    return snake(' '.join(tokens)) or 'unknown_author'


def proposed_ids(frontier, seed_ids):
    used = set(seed_ids)
    result = {}
    for row in frontier:
        key = identity(row)
        decision = CURATION[key]
        author_year = author_id(row) + '_' + snake(row['cited_year'])
        candidate = snake(decision['method_name']) or author_year
        if candidate in used:
            candidate += '_' + author_year
        if candidate in used:
            candidate += '_' + hashlib.sha256(key.encode()).hexdigest()[:8]
        used.add(candidate)
        result[key] = candidate
    return result


def load_inputs():
    _, frontier = read_table(ROOT / 'tables/frontier.tsv')
    _, contexts = read_table(ROOT / 'tables/citation_contexts.tsv')
    _, links = read_table(ROOT / 'tables/context_links.tsv')
    _, seeds = read_table(ROOT / 'seed/seed_list.tsv')
    by_id = {}
    by_work = defaultdict(list)
    title_dois = defaultdict(set)
    for context in contexts:
        if doi(context['cited_doi']):
            title_dois[norm(context['cited_title'])].add(doi(context['cited_doi']))
    for context in contexts:
        cid = context['context_id']
        if cid in by_id:
            raise ValueError('Duplicate citation context ID: ' + cid)
        by_id[cid] = context
        by_work[identity(context)].append(context)
        title_key = norm(context['cited_title'])
        if title_key and title_key != identity(context) and len(title_dois[title_key]) <= 1:
            by_work[title_key].append(context)
    links_by_id = defaultdict(list)
    for link in links:
        links_by_id[link['context_id']].append(link)
    considered = {}
    for row in frontier:
        key = identity(row)
        if key not in CURATION:
            raise ValueError('Frontier identity needs manual sentence review: ' + key)
        group = {}
        for alias in [key, *CURATION[key]['aliases']]:
            for context in by_work.get(alias, []):
                group[context['context_id']] = context
        considered[key] = [dict(context, links=links_by_id[context['context_id']])
                           for context in sorted(group.values(), key=lambda c: c['context_id'])]
        fingerprint = hashlib.sha256(json.dumps(considered[key], sort_keys=True,
                                    ensure_ascii=False).encode()).hexdigest()
        if fingerprint != CURATION[key]['reviewed_sha256']:
            print('Diagnostic: citing sentences or links changed; review identity ' + key,
                  file=sys.stderr)
    return frontier, by_id, considered, {row['paper_id'] for row in seeds}


def lookup_url(row):
    clauses = []
    if doi(row['cited_doi']):
        clauses.append('DOI:"' + doi(row['cited_doi']) + '"')
    if present(row['cited_title']):
        title = row['cited_title'].replace('"', '').replace('\\', ' ')
        clauses.append('TITLE:"' + title + '"')
    if not clauses:
        raise ValueError('No bibliographic identity for metadata lookup')
    return EPMC + '?' + urlencode(sorted({'query': ' OR '.join(clauses),
        'format': 'json', 'resultType': 'core', 'pageSize': 100}.items()))


def cache_path(url):
    return ROOT / 'sources/citations_cache' / (
        'frontier_triage_' + hashlib.sha256(url.encode()).hexdigest() + '.json')


class MetadataClient:
    def __init__(self, offline=False):
        self.offline = offline

    def get(self, row):
        url = lookup_url(row)
        path = cache_path(url)
        record = json.loads(path.read_text()) if path.exists() else {'url': url, 'attempts': []}
        if record.get('url') != url:
            raise ValueError('Cache URL mismatch: ' + path.name)
        if record.get('status') == 200:
            return json.loads(record['body']), path
        if self.offline:
            raise RuntimeError('Offline metadata cache unavailable: ' + path.name)
        import requests

        class PublicSession(requests.Session):
            def rebuild_auth(self, prepared_request, response):
                prepared_request.headers.pop('Authorization', None)

        with PublicSession() as session:
            session.auth = lambda request: request
            session.headers.update({'User-Agent': 'CitationMetadataClient/1.0',
                                    'Accept': 'application/json'})
            for attempt in range(3):
                from citation_paths import pace_request
                pace_request(ROOT / 'sources/citations_cache')
                entry = {'utc': time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime())}
                try:
                    response = session.get(url, timeout=(10, 35), allow_redirects=False)
                    entry.update(status=response.status_code, body=response.text)
                    if response.status_code == 200:
                        payload = response.json()
                        if 'resultList' not in payload or 'hitCount' not in payload:
                            raise ValueError('Invalid Europe PMC search response schema')
                except (requests.RequestException, ValueError) as exc:
                    entry.update(status=0, error=type(exc).__name__ + ': ' + str(exc))
                record['attempts'].append(entry)
                record.update({k: entry.get(k, '') for k in ['status', 'body', 'error']})
                path.write_text(json.dumps(record, ensure_ascii=False, sort_keys=True) + '\n')
                if record['status'] == 200:
                    return payload, path
                if record['status'] not in {0, 429, 500, 502, 503, 504}:
                    break
                if attempt < 2:
                    time.sleep(attempt + 1)
        raise RuntimeError('Metadata lookup failed (not none_found): ' + path.name +
                           ', HTTP ' + str(record['status']))


@lru_cache(maxsize=1)
def repository_routes():
    # Supplement the one required search with already retained repository
    # metadata; this makes no additional service request.
    from citation_contexts import cached_open_routes
    return cached_open_routes(ROOT / 'sources/citations_cache')


def matched_route(row, data):
    reference_doi = doi(row['cited_doi'])
    title = norm(row['cited_title'])
    matched = []
    for item in data.get('resultList', {}).get('result', []):
        same_doi = bool(reference_doi and doi(item.get('doi', '')) == reference_doi)
        same_title = bool(title and SequenceMatcher(None, title, norm(item.get('title', ''))).ratio() >= .92)
        if same_doi or same_title:
            matched.append(item)
    routes = set()
    cached = repository_routes().get(reference_doi) if reference_doi else repository_routes().get(title)
    if cached:
        routes.add(cached['open_route'])
    if reference_doi.startswith('10.48550/arxiv.'):
        routes.add('arxiv')
    for item in matched:
        if item.get('pmcid') or re.fullmatch(r'PMC\d+', str(item.get('id', ''))):
            routes.add('pmc')
        for link in item.get('fullTextUrlList', {}).get('fullTextUrl', []):
            host = (urlsplit(link.get('url', '')).hostname or '').lower()
            if host == 'arxiv.org' or host.endswith('.arxiv.org'):
                routes.add('arxiv')
            if host == 'biorxiv.org' or host.endswith('.biorxiv.org'):
                routes.add('biorxiv')
            if host == 'europepmc.org' and link.get('availabilityCode') == 'OA':
                routes.add('europepmc')
        if item.get('isOpenAccess') == 'Y' and item.get('inEPMC') == 'Y':
            routes.add('europepmc')
    route = next((route for route in ['pmc', 'arxiv', 'biorxiv', 'europepmc'] if route in routes), 'none_found')
    return route, [{'id': item.get('id'), 'source': item.get('source'),
                    'doi': item.get('doi'), 'pmcid': item.get('pmcid')}
                   for item in matched]


def build(offline=False):
    frontier, _, considered, seed_ids = load_inputs()
    proposed = proposed_ids(frontier, seed_ids)
    cache = ROOT / 'sources/citations_cache'
    cache.mkdir(parents=True, exist_ok=True)
    scratch = ROOT / 'tmp/refresh'
    scratch.mkdir(parents=True, exist_ok=True)
    rows, audit = [], {}
    for work in frontier:
        key = identity(work)
        decision = CURATION[key]
        row = {field: work[field] for field in IDENTITY_FIELDS + ['citing_papers']}
        row.update({field: decision[field] for field in ['lineage_role', 'paper_kind', 'why']})
        row.update(follow=expected_follow(row['lineage_role'], row['paper_kind']),
                   context_ids='; '.join(decision['context_ids']), open_route='NA',
                   proposed_paper_id=proposed[key])
        rows.append(row)
        audit[key] = {'considered_context_ids': [c['context_id'] for c in considered[key]],
                      'sentence_sha256': {c['context_id']: hashlib.sha256(c['sentence'].encode()).hexdigest()
                                          for c in considered[key]},
                      'supporting_context_ids': decision['context_ids'],
                      'lookup': None}
    client = MetadataClient(offline)
    yes = [row for row in rows if row['follow'] == 'yes']
    failures = []
    with ThreadPoolExecutor(max_workers=4) as pool:
        tasks = {pool.submit(client.get, row): row for row in yes}
        for completed, future in enumerate(as_completed(tasks), 1):
            row = tasks[future]
            try:
                data, path = future.result()
                row['open_route'], matched = matched_route(row, data)
                audit[identity(row)]['lookup'] = {'service': 'Europe PMC',
                    'url': lookup_url(row), 'cache_file': str(path.relative_to(ROOT)),
                    'http_status': 200, 'hit_count': data['hitCount'],
                    'matched_records': matched, 'open_route': row['open_route'],
                    'retained_repository_evidence': repository_routes().get(doi(row['cited_doi']))
                        if doi(row['cited_doi']) else repository_routes().get(norm(row['cited_title']))}
            except Exception as exc:
                failures.append(str(exc))
                audit[identity(row)]['lookup'] = {'error': str(exc)}
            if completed % 20 == 0 or completed == len(yes):
                print(f'Metadata lookups: {completed}/{len(yes)}; failures: {len(failures)}', flush=True)
    (scratch / 'triage_audit.json').write_text(json.dumps(audit, indent=2, ensure_ascii=False, sort_keys=True) + '\n')
    if failures:
        raise RuntimeError('\n'.join(failures))
    with (ROOT / 'tables/frontier_triage.tsv').open('w', newline='', encoding='utf-8') as handle:
        writer = csv.DictWriter(handle, fieldnames=FIELDS, delimiter='\t', lineterminator='\n')
        writer.writeheader()
        writer.writerows(rows)
    check()


def check():
    frontier, contexts, considered, seed_ids = load_inputs()
    fields, rows = read_table(ROOT / 'tables/frontier_triage.tsv')
    errors = []
    if fields != FIELDS:
        errors.append('Output columns differ from the requested schema')
    signature = lambda row: tuple(row.get(field) for field in IDENTITY_FIELDS)
    if Counter(map(signature, frontier)) != Counter(map(signature, rows)):
        errors.append('Triage must cover every frontier row exactly once')
    original = {identity(row): row for row in frontier}
    proposed = set()
    for row in rows:
        key = identity(row)
        if row['lineage_role'] not in ROLES or row['paper_kind'] not in KINDS:
            errors.append('Invalid role or kind: ' + key)
        if row['follow'] != expected_follow(row['lineage_role'], row['paper_kind']):
            errors.append('Follow rule violated: ' + key)
        evidence = row['context_ids'].split('; ')
        valid_contexts = {context['context_id'] for context in considered.get(key, [])}
        if not evidence or len(evidence) != len(set(evidence)):
            errors.append('Empty or repeated evidence: ' + key)
        for cid in evidence:
            if cid not in contexts:
                errors.append('Unknown context ID: ' + cid)
            elif cid not in valid_contexts:
                errors.append('Context belongs to a different cited work: ' + cid)
        if not row['why'].strip() or len(row['why'].split()) > 20:
            errors.append('Reason must contain 1 to 20 words: ' + key)
        pid = row['proposed_paper_id']
        if not re.fullmatch(r'[a-z][a-z0-9]*(?:_[a-z0-9]+)*', pid):
            errors.append('Invalid snake_case proposed ID: ' + pid)
        if pid in seed_ids or pid in proposed:
            errors.append('Proposed ID collision: ' + pid)
        proposed.add(pid)
        if key in original and row['citing_papers'] != original[key]['citing_papers']:
            errors.append('Citing-paper field differs from frontier: ' + key)
        if row['follow'] == 'no':
            if row['open_route'] != 'NA':
                errors.append('Non-followed work must have NA route: ' + key)
        else:
            if row['open_route'] not in ROUTES:
                errors.append('Invalid followed-work route: ' + key)
            path = cache_path(lookup_url(row))
            if not path.exists():
                errors.append('Missing followed-work metadata cache: ' + key)
            else:
                record = json.loads(path.read_text())
                if record.get('url') != lookup_url(row) or record.get('status') != 200:
                    errors.append('Unsuccessful followed-work metadata lookup: ' + key)
                else:
                    route, _ = matched_route(row, json.loads(record['body']))
                    if route != row['open_route']:
                        errors.append('Route disagrees with cached metadata: ' + key)
    for field in ['lineage_role', 'paper_kind', 'follow', 'open_route']:
        print(field + ': ' + json.dumps(dict(sorted(Counter(row[field] for row in rows).items()))))
    for field in ['lineage_role', 'open_route']:
        print('follow=yes ' + field + ': ' + json.dumps(dict(sorted(Counter(
            row[field] for row in rows if row['follow'] == 'yes').items()))))
    if errors:
        raise ValueError('\n'.join(errors))
    print(f'CHECK PASS: {len(rows)}/{len(frontier)} frontier rows; context IDs, follow rule, '
          'reasons, proposed IDs and cached routes verified.')
    return rows


